solution:
function solve(n, edges, start) {
  const adj = Array.from({ length: n }, () => [])
  for (const [u, v] of edges) {
    adj[u].push(v)
    adj[v].push(u)
  }
  adj.forEach((a) => a.sort((p, q) => p - q))

  const dikunjungi = Array(n).fill(false)
  const urutan = []
  function dfs(u) {
    dikunjungi[u] = true
    urutan.push(u) // catat saat pertama kali dikunjungi
    for (const v of adj[u]) {
      if (!dikunjungi[v]) dfs(v)
    }
  }
  dfs(start)
  return urutan
}
